    KEY_FOLD_BLOCK(aCrystalLaneA, 21U, 153U, aCrystalLaneC, 51U, 124U, aLargeA, 0U);
    KEY_FOLD_BLOCK(aCrystalLaneA, 5U, 248U, aEarthLaneA, 19U, 215U, aLargeA, 1U);
